// Formula parsing and evaluation.
import { parseAddr, toAddr } from "./addr.mjs";

const TOKEN = /\s*(?:(\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)|"((?:[^"]|"")*)"|([A-Za-z_][A-Za-z0-9_.]*)\s*\(|(TRUE|FALSE)(?![A-Za-z0-9_.(])|(\$?[A-Za-z]{1,3}\$?\d+)(?![A-Za-z0-9_.(])|(<>|<=|>=|[-+*\/^&=<>(),:]))/iy;

function tokenize(text) {
  const out = [];
  const end = /\s*/y;
  let pos = 0;
  for (;;) {
    end.lastIndex = pos;
    end.test(text);
    if (end.lastIndex >= text.length) return out;
    TOKEN.lastIndex = pos;
    const m = TOKEN.exec(text);
    if (!m) throw new SyntaxError(`unexpected character at ${end.lastIndex}`);
    pos = TOKEN.lastIndex;
    if (m[1] !== undefined) out.push({ k: "num", v: Number(m[1]) });
    else if (m[2] !== undefined) out.push({ k: "str", v: m[2].replace(/""/g, '"') });
    else if (m[3] !== undefined) out.push({ k: "fn", v: m[3].toUpperCase() });
    else if (m[4] !== undefined) out.push({ k: "bool", v: m[4].toUpperCase() === "TRUE" });
    else if (m[5] !== undefined) out.push({ k: "ref", v: m[5] });
    else out.push({ k: "op", v: m[6] });
  }
}

function refNode(text) {
  let a;
  try { a = parseAddr(text); } catch { throw new SyntaxError(`bad reference: ${text}`); }
  return a;
}

// Parses formula text (without the leading "=") into an AST. Throws SyntaxError on bad syntax.
export function parseFormula(text) {
  const toks = tokenize(String(text));
  let i = 0;
  const peekOp = (...ops) => toks[i] && toks[i].k === "op" && ops.includes(toks[i].v) ? toks[i].v : null;
  const expect = (op) => {
    if (!peekOp(op)) throw new SyntaxError(`expected "${op}"`);
    i++;
  };
  const level = (next, ops) => () => {
    let l = next();
    for (let op; (op = peekOp(...ops)); ) {
      i++;
      l = { t: "bin", op, l, r: next() };
    }
    return l;
  };
  const primary = () => {
    const tok = toks[i++];
    if (!tok) throw new SyntaxError("unexpected end of formula");
    switch (tok.k) {
      case "num": return { t: "num", v: tok.v };
      case "str": return { t: "str", v: tok.v };
      case "bool": return { t: "bool", v: tok.v };
      case "ref": {
        const a = refNode(tok.v);
        if (peekOp(":")) {
          i++;
          const t2 = toks[i++];
          if (!t2 || t2.k !== "ref") throw new SyntaxError("bad range");
          const b = refNode(t2.v);
          return { t: "range", c1: Math.min(a.col, b.col), c2: Math.max(a.col, b.col), r1: Math.min(a.row, b.row), r2: Math.max(a.row, b.row) };
        }
        return { t: "ref", addr: toAddr(a.col, a.row) };
      }
      case "fn": {
        const args = [];
        if (!peekOp(")")) {
          do args.push(cmp()); while (peekOp(",") && i++);
        }
        expect(")");
        return { t: "call", name: tok.v, args };
      }
      default:
        if (tok.v === "(") {
          const e = cmp();
          expect(")");
          return e;
        }
        throw new SyntaxError(`unexpected "${tok.v}"`);
    }
  };
  const unary = () => {
    const op = peekOp("-", "+");
    if (op) {
      i++;
      return { t: "un", op, x: unary() };
    }
    return primary();
  };
  const pow = level(unary, ["^"]);
  const mul = level(pow, ["*", "/"]);
  const add = level(mul, ["+", "-"]);
  const cat = level(add, ["&"]);
  const cmp = level(cat, ["=", "<>", "<", ">", "<=", ">="]);
  const ast = cmp();
  if (i < toks.length) throw new SyntaxError(`unexpected "${toks[i].v}"`);
  return ast;
}

function rangeAddrs(n) {
  const out = [];
  for (let r = n.r1; r <= n.r2; r++) for (let c = n.c1; c <= n.c2; c++) out.push(toAddr(c, r));
  return out;
}

// Normalized addresses the formula reads (ranges expanded row by row), each once, in order of first appearance.
export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    switch (n.t) {
      case "ref": seen.add(n.addr); break;
      case "range": rangeAddrs(n).forEach((a) => seen.add(a)); break;
      case "un": walk(n.x); break;
      case "bin": walk(n.l); walk(n.r); break;
      case "call": n.args.forEach(walk); break;
    }
  };
  walk(ast);
  return [...seen];
}

const isErr = (v) => typeof v === "string" && v.startsWith("#");
const NUM = /^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/i;

// number, or an error string
function num(v) {
  if (v === null) return 0;
  if (typeof v === "number") return v;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (isErr(v)) return v;
  const t = v.trim();
  return NUM.test(t) ? Number(t) : "#VALUE!";
}

// string, or an error string is indistinguishable, so callers check isErr on the input first
function text(v) {
  if (v === null) return "";
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

// boolean, or an error string
function bool(v) {
  if (v === null) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  if (isErr(v)) return v;
  const u = v.trim().toUpperCase();
  return u === "TRUE" ? true : u === "FALSE" ? false : "#VALUE!";
}

const fin = (n) => (Number.isFinite(n) ? (n === 0 ? 0 : n) : "#NUM!");

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null && b === null) return 0;
  if (a === null) a = typeof b === "number" ? 0 : typeof b === "string" ? "" : false;
  if (b === null) b = typeof a === "number" ? 0 : typeof a === "string" ? "" : false;
  if (rank(a) !== rank(b)) return rank(a) - rank(b);
  if (typeof a === "string") { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

function round(x, d) {
  d = Math.trunc(d);
  const abs = Math.abs(x);
  let r;
  const s = String(abs);
  if (s.includes("e")) r = Math.round(abs * 10 ** d) / 10 ** d;
  else r = Number(Math.round(Number(`${s}e${d}`)) + `e${-d}`);
  return fin(x < 0 ? -r : r);
}

// The formula's value; lookup(addr) gives a cell's value (null when empty).
export function evaluate(ast, lookup) {
  const ev = (n) => {
    switch (n.t) {
      case "num": case "str": case "bool": return n.v;
      case "ref": return lookup(n.addr);
      case "range": return "#VALUE!";
      case "un": {
        const v = ev(n.x);
        if (isErr(v)) return v;
        const x = num(v);
        if (typeof x === "string") return x;
        return fin(n.op === "-" ? 0 - x : x);
      }
      case "bin": return binary(n);
      case "call": return call(n);
    }
  };

  const binary = ({ op, l, r }) => {
    const a = ev(l), b = ev(r);
    if (isErr(a)) return a;
    if (isErr(b)) return b;
    if (op === "&") return text(a) + text(b);
    if (["=", "<>", "<", ">", "<=", ">="].includes(op)) {
      const c = compare(a, b);
      switch (op) {
        case "=": return c === 0;
        case "<>": return c !== 0;
        case "<": return c < 0;
        case ">": return c > 0;
        case "<=": return c <= 0;
        default: return c >= 0;
      }
    }
    const x = num(a);
    if (typeof x === "string") return x;
    const y = num(b);
    if (typeof y === "string") return y;
    switch (op) {
      case "+": return fin(x + y);
      case "-": return fin(x - y);
      case "*": return fin(x * y);
      case "/": return y === 0 ? "#DIV/0!" : fin(x / y);
      default: return fin(x ** y);
    }
  };

  // Calls f(value) for each cell of a range argument or the value of a direct one; returns an error to stop early.
  const each = (args, f) => {
    for (const a of args) {
      if (a.t === "range") {
        for (const addr of rangeAddrs(a)) {
          const v = lookup(addr);
          if (isErr(v)) return v;
          f(v, true);
        }
      } else {
        const v = ev(a);
        if (isErr(v)) return v;
        f(v, false);
      }
    }
    return undefined;
  };

  const numbers = (args) => {
    const xs = [];
    let bad;
    const err = each(args, (v, inRange) => {
      if (bad) return;
      if (inRange) {
        if (typeof v === "number") xs.push(v);
        return;
      }
      const x = num(v);
      if (typeof x === "string") bad = x;
      else xs.push(x);
    });
    return err || bad || xs;
  };

  const call = ({ name, args }) => {
    const n = args.length;
    const arity = (min, max) => n >= min && n <= max;
    const one = (f) => {
      if (n !== 1) return "#VALUE!";
      const v = ev(args[0]);
      return isErr(v) ? v : f(v);
    };
    switch (name) {
      case "SUM": case "AVERAGE": case "MIN": case "MAX": {
        const xs = numbers(args);
        if (typeof xs === "string") return xs;
        if (name === "SUM") return fin(xs.reduce((s, x) => s + x, 0));
        if (name === "AVERAGE") return xs.length ? fin(xs.reduce((s, x) => s + x, 0) / xs.length) : "#DIV/0!";
        if (!xs.length) return 0;
        return name === "MIN" ? Math.min(...xs) : Math.max(...xs);
      }
      case "COUNT": {
        let c = 0;
        for (const a of args) {
          if (a.t === "range") {
            for (const addr of rangeAddrs(a)) if (typeof lookup(addr) === "number") c++;
          } else if (typeof ev(a) === "number") c++;
        }
        return c;
      }
      case "IF": {
        if (!arity(2, 3)) return "#VALUE!";
        const c = bool(ev(args[0]));
        if (typeof c === "string") return c;
        if (c) return ev(args[1]);
        return n === 3 ? ev(args[2]) : false;
      }
      case "AND": case "OR": {
        if (n < 1) return "#VALUE!";
        const bs = [];
        let bad;
        const err = each(args, (v, inRange) => {
          if (bad) return;
          if (inRange) {
            if (typeof v === "number" || typeof v === "boolean") bs.push(bool(v));
            return;
          }
          const b = bool(v);
          if (typeof b === "string") bad = b;
          else bs.push(b);
        });
        if (err || bad) return err || bad;
        return name === "AND" ? bs.every(Boolean) : bs.some(Boolean);
      }
      case "NOT": return one((v) => {
        const b = bool(v);
        return typeof b === "string" ? b : !b;
      });
      case "ROUND": {
        if (n !== 2) return "#VALUE!";
        const a = ev(args[0]), b = ev(args[1]);
        if (isErr(a)) return a;
        if (isErr(b)) return b;
        const x = num(a);
        if (typeof x === "string") return x;
        const d = num(b);
        if (typeof d === "string") return d;
        return round(x, d);
      }
      case "ABS": return one((v) => {
        const x = num(v);
        return typeof x === "string" ? x : Math.abs(x);
      });
      case "LEN": return one((v) => text(v).length);
      case "UPPER": return one((v) => text(v).toUpperCase());
      case "LOWER": return one((v) => text(v).toLowerCase());
      case "CONCAT": {
        let s = "";
        const err = each(args, (v) => { s += text(v); });
        return err || s;
      }
      default: return "#NAME?";
    }
  };

  return ev(ast);
}
