import test from "node:test";
import assert from "node:assert/strict";
import { parseFormula, refsOf, evaluate } from "../src/formula.mjs";

const cells = { A1: 1, A2: 2, B1: "x", B2: null, C1: "#REF!" };
const run = (f) => evaluate(parseFormula(f), (a) => cells[a] ?? null);

test("operators and precedence", () => {
  assert.equal(run("-2^2"), 4);
  assert.equal(run("2^3^2"), 64);
  assert.equal(run('"a"&1+2'), "a3");
  assert.equal(run("1/0"), "#DIV/0!");
  assert.equal(run('"abc"="ABC"'), true);
  assert.equal(run("A1:B2"), "#VALUE!");
  assert.throws(() => parseFormula("1+"), SyntaxError);
});

test("functions", () => {
  assert.equal(run("SUM(A1:B2, 3)"), 6);
  assert.equal(run("count(A1:B2,1,\"2\")"), 3 - 1);
  assert.equal(run("IF(A1, \"y\", 1/0)"), "y");
  assert.equal(run("ROUND(-2.5, 0)"), -3);
  assert.equal(run("ROUND(1.005, 2)"), 1.01);
  assert.equal(run("CONCAT(A1:B2)"), "12x");
  assert.equal(run("FOO(1)"), "#NAME?");
  assert.equal(run("SUM(C1:C1)"), "#REF!");
});

test("refsOf", () => {
  assert.deepEqual(refsOf(parseFormula("$b$2+SUM(A1:B2)")), ["B2", "A1", "B1", "A2"]);
});
