// Recalculation: cell values, cycle detection and dependents.
import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, toAddr } from "./addr.mjs";
import { cellAddrs } from "./sheet.mjs";

export function valueOf(raw) {
  if (raw === "" || raw == null) return null;
  const t = raw.trim();
  if (t !== "" && Number.isFinite(Number(t))) return Number(t);
  const u = t.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw.startsWith("'")) return raw.slice(1);
  return raw;
}

const norm = (addr) => { const a = parseAddr(addr); return toAddr(a.col, a.row); };

// Formula cells: addr -> { ast, deps } (deps are formula cells only); ast null when unparseable.
function buildGraph(sheet) {
  const nodes = new Map();
  for (const addr of cellAddrs(sheet)) {
    const raw = sheet.cells.get(addr);
    if (!raw.startsWith("=")) continue;
    let ast = null, refs = [];
    try { ast = parseFormula(raw.slice(1)); refs = refsOf(ast); } catch { ast = null; refs = []; }
    nodes.set(addr, { ast, refs });
  }
  for (const n of nodes.values()) n.deps = n.refs.filter((r) => nodes.has(r));
  return nodes;
}

// Iterative Tarjan: returns SCCs, dependencies before dependents.
function sccs(nodes) {
  const index = new Map(), low = new Map(), onStack = new Set(), stack = [], out = [];
  let counter = 0;
  for (const root of nodes.keys()) {
    if (index.has(root)) continue;
    const work = [[root, 0]];
    index.set(root, counter); low.set(root, counter++); stack.push(root); onStack.add(root);
    while (work.length) {
      const frame = work[work.length - 1];
      const [v, i] = frame;
      const deps = nodes.get(v).deps;
      if (i < deps.length) {
        frame[1]++;
        const w = deps[i];
        if (!index.has(w)) {
          index.set(w, counter); low.set(w, counter++); stack.push(w); onStack.add(w);
          work.push([w, 0]);
        } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) { const p = work[work.length - 1][0]; low.set(p, Math.min(low.get(p), low.get(v))); }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); comp.push(w); } while (w !== v);
          out.push(comp);
        }
      }
    }
  }
  return out;
}

const cyclic = (nodes, comp) => comp.length > 1 || nodes.get(comp[0]).deps.includes(comp[0]);

export function computeAll(sheet) {
  const nodes = buildGraph(sheet);
  const values = new Map();
  for (const addr of cellAddrs(sheet)) {
    if (!nodes.has(addr)) values.set(addr, valueOf(sheet.cells.get(addr)));
  }
  const lookup = (a) => values.get(norm(a)) ?? null;
  for (const comp of sccs(nodes)) {
    if (cyclic(nodes, comp)) { for (const a of comp) values.set(a, "#CYCLE!"); continue; }
    const { ast } = nodes.get(comp[0]);
    let v;
    if (!ast) v = "#ERROR!";
    else { try { v = evaluate(ast, lookup); } catch { v = "#ERROR!"; } }
    values.set(comp[0], v);
  }
  const ordered = new Map();
  for (const addr of cellAddrs(sheet)) ordered.set(addr, values.get(addr));
  return ordered;
}

const rank = (a) => { const { col, row } = parseAddr(a); return row * 20000 + col; };

export function dependents(sheet, addr) {
  const start = norm(addr);
  const nodes = buildGraph(sheet);
  const cyc = new Set();
  for (const comp of sccs(nodes)) if (cyclic(nodes, comp)) comp.forEach((a) => cyc.add(a));
  const rev = new Map();
  for (const [a, n] of nodes) for (const r of n.refs) {
    if (!rev.has(r)) rev.set(r, []);
    rev.get(r).push(a);
  }
  const seen = new Set([start]), todo = [start];
  while (todo.length) for (const d of rev.get(todo.pop()) ?? []) if (!seen.has(d)) { seen.add(d); todo.push(d); }
  const set = new Set([...seen].filter((a) => a !== start && nodes.has(a) && !cyc.has(a)));
  const pending = new Map(), users = new Map();
  for (const a of set) {
    const deps = new Set(nodes.get(a).refs.filter((r) => set.has(r)));
    pending.set(a, deps.size);
    for (const d of deps) { if (!users.has(d)) users.set(d, []); users.get(d).push(a); }
  }
  // Min-heap by (row, col).
  const heap = [];
  const push = (a) => {
    heap.push(a);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (rank(heap[p]) <= rank(heap[i])) break;
      [heap[p], heap[i]] = [heap[i], heap[p]]; i = p;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        let m = i;
        for (const c of [2 * i + 1, 2 * i + 2]) if (c < heap.length && rank(heap[c]) < rank(heap[m])) m = c;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]]; i = m;
      }
    }
    return top;
  };
  for (const [a, n] of pending) if (n === 0) push(a);
  const out = [];
  while (heap.length) {
    const a = pop();
    out.push(a);
    for (const u of users.get(a) ?? []) if (--pending.set(u, pending.get(u) - 1).get(u) === 0) push(u);
  }
  return out;
}
