// Table operations: range sorting and pivots.
import { parseAddr, toAddr, colIndex } from "./addr.mjs";
import { getCell, setCell } from "./sheet.mjs";
import { valueOf } from "./recalc.mjs";

const parseRange = (range) => {
  const [a, b] = range.split(":");
  const p = parseAddr(a), q = parseAddr(b ?? a);
  return { c1: Math.min(p.col, q.col), c2: Math.max(p.col, q.col), r1: Math.min(p.row, q.row), r2: Math.max(p.row, q.row) };
};

const typeRank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

// Orders non-empty values: numbers, strings (case-insensitive), booleans (false first).
function compareValues(a, b) {
  const ra = typeRank(a), rb = typeRank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

export function sortRange(sheet, range, keys, options = {}) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const start = options.header ? r1 + 1 : r1;
  const rows = [];
  for (let r = start; r <= r2; r++) {
    const raws = [];
    for (let c = c1; c <= c2; c++) raws.push(getCell(sheet, toAddr(c, r)));
    rows.push(raws);
  }
  const ks = keys.map((k) => ({ i: colIndex(k.col) - c1, desc: !!k.desc }));
  const vals = new Map(rows.map((row) => [row, ks.map((k) => valueOf(row[k.i]))]));
  rows.sort((x, y) => {
    const vx = vals.get(x), vy = vals.get(y);
    for (let n = 0; n < ks.length; n++) {
      const a = vx[n], b = vy[n];
      if (a == null || b == null) { if (a == null && b == null) continue; return a == null ? 1 : -1; }
      const d = compareValues(a, b);
      if (d) return ks[n].desc ? -d : d;
    }
    return 0;
  });
  rows.forEach((raws, k) => raws.forEach((raw, j) => setCell(sheet, toAddr(c1 + j, start + k), raw)));
}

export function pivot(values, range, { rows, value, agg }) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const header = new Map();
  for (let c = c1; c <= c2; c++) {
    const name = values.get(toAddr(c, r1));
    if (name != null && !header.has(String(name))) header.set(String(name), c);
  }
  for (const name of [rows, value]) if (!header.has(name)) throw new Error(`no such column: ${name}`);
  const kc = header.get(rows), vc = header.get(value);
  const groups = new Map();
  for (let r = r1 + 1; r <= r2; r++) {
    const k = values.get(toAddr(kc, r)) ?? null;
    const id = k === null ? "b" : `${typeof k}:${k}`;
    if (!groups.has(id)) groups.set(id, { key: k, vals: [] });
    groups.get(id).vals.push(values.get(toAddr(vc, r)) ?? null);
  }
  const reduce = (vals) => {
    if (agg === "count") return vals.filter((v) => v != null).length;
    const nums = vals.filter((v) => typeof v === "number");
    if (agg === "sum") return nums.reduce((s, v) => s + v, 0);
    if (!nums.length) return null;
    if (agg === "avg") return nums.reduce((s, v) => s + v, 0) / nums.length;
    if (agg === "min") return nums.reduce((m, v) => Math.min(m, v));
    if (agg === "max") return nums.reduce((m, v) => Math.max(m, v));
    throw new Error(`unknown aggregate: ${agg}`);
  };
  const all = [...groups.values()];
  const named = all.filter((g) => g.key !== null).sort((a, b) => compareValues(a.key, b.key));
  const blank = all.filter((g) => g.key === null);
  return [...named, ...blank].map((g) => ({ key: g.key === null ? "(blank)" : g.key, value: reduce(g.vals) }));
}
