// Subset of spreadsheet number formats.

function splitSections(pattern) {
  const out = [];
  let cur = "";
  let quoted = false;
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    if (c === "\\") { cur += c + (pattern[++i] ?? ""); continue; }
    if (c === '"') quoted = !quoted;
    if (c === ";" && !quoted) { out.push(cur); cur = ""; continue; }
    cur += c;
  }
  out.push(cur);
  return out;
}

function tokenize(section) {
  const toks = [];
  for (let i = 0; i < section.length; i++) {
    const c = section[i];
    if (c === '"') {
      let j = section.indexOf('"', i + 1);
      if (j < 0) j = section.length;
      toks.push({ t: "lit", v: section.slice(i + 1, j) });
      i = j;
    } else if (c === "\\") {
      toks.push({ t: "lit", v: section[++i] ?? "" });
    } else if ((c === "E" || c === "e") && (section[i + 1] === "+" || section[i + 1] === "-")) {
      let n = 0;
      let j = i + 2;
      while (section[j] === "0") { n++; j++; }
      toks.push({ t: "exp", plus: section[i + 1] === "+", min: n });
      i = j - 1;
    } else if (c === "0" || c === "#") toks.push({ t: "d", v: c });
    else if (c === "." || c === "," || c === "%") toks.push({ t: c });
    else toks.push({ t: "lit", v: c });
  }
  return toks;
}

// Decimal expansion of a non-negative finite number as printed by JS:
// digits (no leading zeros except possibly "0") and the count of integer digits.
function decimal(abs) {
  let s = String(abs);
  let exp = 0;
  const m = /^([\d.]+)e([+-]\d+)$/.exec(s);
  if (m) { s = m[1]; exp = Number(m[2]); }
  let [i, f = ""] = s.split(".");
  let digits = i + f;
  let point = i.length + exp;
  if (point < 0) { digits = "0".repeat(-point) + digits; point = 0; }
  else if (point > digits.length) digits += "0".repeat(point - digits.length);
  return { digits, point };
}

// Round digit string keeping `keep` digits (half away from zero); returns {digits, point}.
function roundDigits({ digits, point }, keep) {
  if (keep < 0) return { digits: "0", point: 1 };
  if (digits.length <= keep) return { digits: digits.padEnd(keep, "0"), point };
  const up = digits[keep] >= "5";
  let kept = digits.slice(0, keep);
  if (up) {
    const n = (BigInt("1" + kept) + 1n).toString();
    if (n.length > keep + 1) point++; // carried into a new digit
    kept = n.slice(1);
    if (n.length > keep + 1) kept = n; 
  }
  return { digits: kept, point };
}

function group(s) {
  return s.replace(/\B(?=(\d{3})+$)/g, ",");
}

function renderSection(abs, section) {
  const toks = tokenize(section);
  let pct = toks.some((t) => t.t === "%");
  const dot = toks.findIndex((t) => t.t === ".");
  const expTok = toks.find((t) => t.t === "exp");
  const isInt = (t, k) => t.t === "d" && (dot < 0 || k < dot);
  let intZeros = 0;
  let decimals = 0;
  let minDec = 0;
  let grouped = false;
  toks.forEach((t, k) => {
    if (t.t === "d") {
      if (isInt(t, k)) { if (t.v === "0") intZeros++; }
      else { decimals++; if (t.v === "0") minDec = decimals; }
    } else if (t.t === ",") {
      const before = toks.slice(0, k).some((u, j) => isInt(u, j));
      const after = toks.slice(k + 1).some((u, j) => isInt(u, j + k + 1));
      if (before && after) grouped = true;
    }
  });

  let dec = decimal(abs);
  if (pct) dec = { digits: dec.digits, point: dec.point + 2 };
  if (dec.point > dec.digits.length) dec.digits = dec.digits.padEnd(dec.point, "0");

  let intStr, fracStr, expStr = "";
  if (expTok) {
    const lead = dec.digits.search(/[1-9]/);
    let e = 0;
    let d = "0";
    if (lead >= 0) { d = dec.digits.slice(lead); e = dec.point - lead - 1; }
    const r = roundDigits({ digits: d, point: 1 }, 1 + decimals);
    if (r.point > 1) e++;
    const all = r.point > 1 ? r.digits.slice(0, 1 + decimals) : r.digits;
    intStr = all.slice(0, 1);
    fracStr = all.slice(1);
    const ea = String(Math.abs(e)).padStart(expTok.min, "0");
    expStr = "E" + (e < 0 ? "-" : expTok.plus ? "+" : "") + ea;
  } else {
    const r = roundDigits(dec, dec.point + decimals);
    intStr = r.digits.slice(0, r.point).replace(/^0+/, "");
    fracStr = r.digits.slice(r.point);
    intStr = intStr.padStart(intZeros, "0");
    if (grouped) intStr = group(intStr);
  }
  fracStr = fracStr.padEnd(decimals, "0");
  while (fracStr.length > minDec && fracStr.endsWith("0")) fracStr = fracStr.slice(0, -1);
  const nonZero = /[1-9]/.test(intStr + fracStr);

  let out = "";
  let intDone = false;
  let fracDone = false;
  toks.forEach((t, k) => {
    if (t.t === "lit") out += t.v;
    else if (t.t === "%") out += "%";
    else if (t.t === ".") out += ".";
    else if (t.t === "exp") out += expStr;
    else if (t.t === "d") {
      if (isInt(t, k)) { if (!intDone) { out += intStr; intDone = true; } }
      else if (!fracDone) { out += fracStr; fracDone = true; }
    }
  });
  return { text: out, nonZero };
}

export function formatNumber(value, pattern) {
  if (value === null || value === undefined) return "";
  if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
  if (typeof value !== "number") return String(value);
  if (pattern === "General" || !Number.isFinite(value)) return String(value);
  const secs = splitSections(pattern);
  const neg = value < 0;
  const abs = Math.abs(value);
  let sec = secs[0];
  let own = false;
  if (secs.length >= 2 && neg) { sec = secs[1]; own = true; }
  else if (secs.length >= 3 && value === 0) sec = secs[2];
  const { text, nonZero } = renderSection(abs, sec);
  return neg && !own && nonZero ? "-" + text : text;
}
