import { createSheet, setCell, cellAddrs, getCell } from "./sheet.mjs";
import { parseAddr, toAddr } from "./addr.mjs";

const text = (v) => (v == null ? "" : v === true ? "TRUE" : v === false ? "FALSE" : String(v));

const quote = (s) => (/[,"\n\r]/.test(s) || s.startsWith(" ") || s.endsWith(" ") ? `"${s.replace(/"/g, '""')}"` : s);

export function toCSV(sheet, values = null) {
  const addrs = cellAddrs(sheet);
  if (!addrs.length) return "";
  let rows = 0, cols = 0;
  for (const a of addrs) {
    const p = parseAddr(a);
    rows = Math.max(rows, p.row + 1);
    cols = Math.max(cols, p.col + 1);
  }
  let out = "";
  for (let r = 0; r < rows; r++) {
    const fields = [];
    for (let c = 0; c < cols; c++) {
      const a = toAddr(c, r);
      fields.push(quote(values ? text(values.get(a)) : getCell(sheet, a)));
    }
    out += fields.join(",") + "\n";
  }
  return out;
}

function detectDelimiter(src) {
  const n = { ",": 0, ";": 0, "\t": 0 };
  let inQ = false;
  for (const ch of src) {
    if (ch === '"') inQ = !inQ;
    else if (!inQ) {
      if (ch === "\n") break;
      if (ch in n) n[ch]++;
    }
  }
  let best = ",";
  for (const d of [";", "\t"]) if (n[d] > n[best]) best = d;
  return best;
}

export function fromCSV(src, options = {}) {
  const delim = options.delimiter ?? detectDelimiter(src);
  const sheet = createSheet();
  let row = 0, line = 1, i = 0;
  const put = (col, s) => {
    if (s === "") return;
    setCell(sheet, toAddr(col, row), !options.formulas && s.startsWith("=") ? "'" + s : s);
  };
  while (i < src.length) {
    let col = 0;
    for (;;) {
      let field = "";
      if (src[i] === '"') {
        const startLine = line;
        i++;
        for (;;) {
          if (i >= src.length) throw new Error(`unclosed quote at line ${startLine}`);
          const ch = src[i];
          if (ch === '"') {
            if (src[i + 1] === '"') { field += '"'; i += 2; continue; }
            i++;
            break;
          }
          if (ch === "\n") line++;
          field += ch;
          i++;
        }
      }
      while (i < src.length && src[i] !== delim && src[i] !== "\n" && !(src[i] === "\r" && src[i + 1] === "\n")) field += src[i++];
      put(col++, field);
      if (src[i] === delim) { i++; continue; }
      if (src[i] === "\r") i++;
      if (src[i] === "\n") { i++; line++; }
      break;
    }
    row++;
  }
  return sheet;
}
