import { parseAddr, toAddr, colIndex, colName } from "./addr.mjs";

const REF = "(\\$?[A-Za-z]{1,3}\\$?[1-9]\\d*)";
const TOKEN = new RegExp(`"(?:[^"]|"")*"|(?<![A-Za-z0-9_.])${REF}(?::${REF})?(?![A-Za-z0-9_.(])`, "g");

const fmt = (p) => `${p.colAbs ? "$" : ""}${colName(p.col)}${p.rowAbs ? "$" : ""}${p.row + 1}`;

// Maps a single index; null when deleted.
function mapOne(n, at, count, del) {
  if (!del) return n >= at ? n + count : n;
  if (n < at) return n;
  return n >= at + count ? n - count : null;
}

// Maps a range's ends; null when the whole range is deleted.
function mapRange(lo, hi, at, count, del) {
  if (!del) return [lo >= at ? lo + count : lo, hi >= at ? hi + count : hi];
  const end = at + count;
  if (lo >= at && hi < end) return null;
  return [lo < at ? lo : lo >= end ? lo - count : at, hi >= end ? hi - count : hi >= at ? at - 1 : hi];
}

function rewrite(raw, axis, at, count, del) {
  if (!raw.startsWith("=")) return raw;
  return raw.replace(TOKEN, (m, a, b) => {
    if (m[0] === '"') return m;
    const p = parseAddr(a);
    if (!b) {
      const n = mapOne(p[axis], at, count, del);
      if (n === null) return "#REF!";
      return fmt({ ...p, [axis]: n });
    }
    const q = parseAddr(b);
    const r = mapRange(p[axis], q[axis], at, count, del);
    if (!r) return "#REF!";
    return `${fmt({ ...p, [axis]: r[0] })}:${fmt({ ...q, [axis]: r[1] })}`;
  });
}

function apply(sheet, axis, at, count, del) {
  const next = new Map();
  for (const [addr, raw] of sheet.cells) {
    const p = parseAddr(addr);
    const n = mapOne(p[axis], at, count, del);
    if (n === null) continue;
    const q = { ...p, [axis]: n };
    next.set(toAddr(q.col, q.row), rewrite(raw, axis, at, count, del));
  }
  sheet.cells = next;
  return sheet;
}

export const insertRows = (sheet, at, count = 1) => apply(sheet, "row", at - 1, count, false);
export const deleteRows = (sheet, at, count = 1) => apply(sheet, "row", at - 1, count, true);
export const insertCols = (sheet, at, count = 1) => apply(sheet, "col", colIndex(at), count, false);
export const deleteCols = (sheet, at, count = 1) => apply(sheet, "col", colIndex(at), count, true);
